const test   = require('node:test');
const assert = require('node:assert');
const fs     = require('fs');
const path   = require('path');
const { ROOT, makeSandbox, loadPrivate, fakeAnthropic } = require('./helpers');

// ─── RAG index contents ───────────────────────────────────────────────────────

test('RAG index skips README.md files, _ folders and files, and raw *_ann / *_tweet folders', () => {
    const { collectMdFiles } = loadPrivate('src/rag.js', ['collectMdFiles'], (p) => (p.endsWith('embedder') ? { embed: async () => [] } : require(p)));
    const box = makeSandbox([], {
        'kb/README.md': '# notes', 'kb/core-facts.md': 'x', 'kb/_context.md': 'x',
        'kb/corrections/_drafts/a.md': 'draft', 'kb/corrections/a.md': 'x',
        'kb/announcements/May_ann/week1.md': 'raw', 'kb/announcements/milestones.md': 'x', 'kb/tweets/May_tweet/week1.md': 'raw',
    });
    try {
        const labels = collectMdFiles(box.path('kb'), 'kb').map(f => f.label).sort();
        assert.deepStrictEqual(labels, ['kb/announcements/milestones.md', 'kb/core-facts.md', 'kb/corrections/a.md']);
    } finally { box.cleanup(); }
});

test('EXCLUDE: a closed <!-- EXCLUDE --> … <!-- /EXCLUDE --> section is stripped before chunking', () => {
    const src = fs.readFileSync(path.join(ROOT, 'src/rag.js'), 'utf8');
    const re = src.match(/raw\.replace\((\/.*?\/gi)/)[1];
    const strip = (t) => t.replace(eval(re), '');   // the exact regex buildIndex uses
    assert.strictEqual(strip('keep <!-- EXCLUDE -->hide<!-- /EXCLUDE --> keep').replace(/\s+/g, ' '), 'keep keep');
    assert.strictEqual(strip('keep <!-- EXCLUDE -->hide everything after').trim(), 'keep', 'an unclosed marker hides to the end');
});

// ─── Search cache ─────────────────────────────────────────────────────────────

test('searchKB reads the index file once, and reloads it only after the file changes', async () => {
    const vec = (x) => [x, 1 - x];
    const cacheFile = (chunks) => JSON.stringify({ version: 1, chunks: chunks.map((t, i) => ({ id: `f::${i}`, file: 'knowledge-base/docs/a.md', chunkIndex: i, text: t, hash: 'h', embedding: vec(i ? 0 : 1) })) });
    const box = makeSandbox(['src/rag.js'], {
        'src/embedder.js': "module.exports = { embed: async (texts) => texts.map(() => [1, 0]) };",
        'knowledge-base/.embeddings-cache.json': cacheFile(['first version']),
    });
    const realRead = fs.readFileSync;
    let reads = 0;
    fs.readFileSync = function (p, ...rest) { if (String(p).endsWith('.embeddings-cache.json')) reads++; return realRead.call(this, p, ...rest); };
    try {
        const { searchKB } = require(box.path('src/rag.js'));
        assert.match((await searchKB('q')).context, /first version/);
        await searchKB('q'); await searchKB('q');
        assert.strictEqual(reads, 1, 'three searches, one read');
        await new Promise(r => setTimeout(r, 20));
        fs.writeFileSync(box.path('knowledge-base/.embeddings-cache.json'), cacheFile(['second version']));
        assert.match((await searchKB('q')).context, /second version/, 'a changed file is picked up');
        assert.strictEqual(reads, 2);
    } finally { fs.readFileSync = realRead; box.cleanup(); }
});

// ─── Exclusions survive a re-scrape ───────────────────────────────────────────

test('reapplyExclusions keeps whole-file and partial exclusions when a page is re-scraped', () => {
    const { reapplyExclusions } = loadPrivate('src/kb-sync.js', ['reapplyExclusions']);
    const header = '# Blog: x\nSource: u\nScraped: t\n\n---\n\n';
    const fresh = 'Intro.\n\nOld rate table: 0.03\n\nOutro.';
    const whole = reapplyExclusions(`${header}<!-- EXCLUDE -->\n\nold text\n\n<!-- /EXCLUDE -->`, fresh);
    assert.strictEqual(whole.body, `<!-- EXCLUDE -->\n\n${fresh}\n\n<!-- /EXCLUDE -->`, 'closed whole-file exclusion wraps the new text');
    const lone = reapplyExclusions(`${header}<!-- EXCLUDE -->\n\nold text`, fresh);
    assert.strictEqual(lone.body, whole.body, 'a lone marker (old sync form) also becomes a whole-file exclusion');
    const partial = reapplyExclusions(`${header}Intro.\n\n<!-- EXCLUDE -->\nOld rate table: 0.03\n<!-- /EXCLUDE -->\n\nOutro.`, fresh);
    assert.match(partial.body, /<!-- EXCLUDE -->\nOld rate table: 0\.03\n<!-- \/EXCLUDE -->/);
    assert.deepStrictEqual(partial.lost, []);
    const lost = reapplyExclusions(`${header}Intro.\n\n<!-- EXCLUDE -->\nA paragraph that was rewritten\n<!-- /EXCLUDE -->`, fresh);
    assert.strictEqual(lost.body, fresh, 'nothing is guessed when the excluded text changed');
    assert.strictEqual(lost.lost.length, 1, 'and it is reported');
    assert.strictEqual(reapplyExclusions(`${header}no markers`, fresh).body, fresh);
});

// ─── Blog article numbering ───────────────────────────────────────────────────

test('blogFileForUrl: next number follows the highest article, and a known URL reuses its file', () => {
    const box = makeSandbox(['src/kb-sync.js', 'src/blog-scraper.js', 'src/utils.js'], {
        'knowledge-base/blogs/_index.json': JSON.stringify({ pages: [{ url: 'https://blog.riverai.inc/known/', slug: 'known', file: 'known.md' }] }),
        'knowledge-base/blogs/October_blog/article1.md': 'a', 'knowledge-base/blogs/October_blog/article3.md': 'c',
    });
    try {
        const { blogFileForUrl } = require(box.path('src/kb-sync.js'));
        assert.deepStrictEqual(blogFileForUrl('https://blog.riverai.inc/new/', 'October'), { file: 'October_blog/article4.md', slug: 'article4' },
            'article2 was removed — counting files would give article3 and overwrite it');
        assert.deepStrictEqual(blogFileForUrl('https://blog.riverai.inc/known/', 'October'), { file: 'known.md', slug: 'known' });
        assert.deepStrictEqual(blogFileForUrl('https://blog.riverai.inc/x/', 'November'), { file: 'November_blog/article1.md', slug: 'article1' });
    } finally { box.cleanup(); }
});

// ─── Announcement scan ────────────────────────────────────────────────────────

test('announcement scan: a failed Haiku call is retried on the next scan, and a success is not repeated', async () => {
    const entry = (iso, text) => `\n\n---\n*${iso}*\n${text}`;
    const box = makeSandbox(['src/kb-monitor.js'], {
        'knowledge-base/announcements/_scan-state.json': JSON.stringify({ lastScanned: '2026-10-01T00:00:00.000Z' }),
        'knowledge-base/announcements/October_ann/week2.md': entry('2026-10-09T04:56:01.390Z', 'Season 7 is live, Oct 1 - Dec 31') + entry('2026-10-10T00:00:00.000Z', 'Second announcement'),
        'knowledge-base/announcements/ecosystem-milestones.md': '# Milestones',
        'knowledge-base/blogs/_index.json': JSON.stringify({ pages: [] }),
    });
    try {
        let failFirst = true;
        const ai = fakeAnthropic((req) => {
            const text = req.messages[0].content;
            if (failFirst && text.includes('Season 7')) { failFirst = false; throw new Error('overloaded'); }
            return 'YES MILESTONE\nA new fact.';
        });
        const { createMonitorModule } = require(box.path('src/kb-monitor.js'));
        const monitor = createMonitorModule(ai, {});
        const first = await monitor.scanAnnouncementsForNewFacts();
        assert.strictEqual(first.found.length, 1, 'first scan: one success, one failure');
        const state = JSON.parse(fs.readFileSync(box.path('knowledge-base/announcements/_scan-state.json'), 'utf8'));
        assert.deepStrictEqual(state.retry, ['2026-10-09T04:56:01.390Z'], 'the failed entry is kept for retry');
        const second = await monitor.scanAnnouncementsForNewFacts();
        assert.strictEqual(second.scanned, 1, 'second scan looks only at the failed entry');
        assert.strictEqual(second.found.length, 1, 'and succeeds this time');
        const third = await monitor.scanAnnouncementsForNewFacts();
        assert.strictEqual(third.scanned, 0, 'nothing left to retry');
    } finally { box.cleanup(); }
});

// ─── Staleness check ──────────────────────────────────────────────────────────

test('staleness check reviews corrections plus core-facts.md, and rejects names the model invents', async () => {
    const box = makeSandbox(['src/kb-monitor.js'], {
        'knowledge-base/core-facts.md': '- Current season: Season 5',
        'knowledge-base/corrections/conversion-mechanism.md': 'S6 parameters',
        'knowledge-base/announcements/_scan-state.json': '{}',
    });
    try {
        const ai = fakeAnthropic((req) => (req.model.includes('haiku')
            ? ((req.system?.[0]?.text ?? '').includes('[core-facts.md]') ? 'core-facts.md\nmade-up.md' : 'NONE')
            : 'NO_CHANGE_NEEDED'));
        const { createMonitorModule } = require(box.path('src/kb-monitor.js'));
        const m = createMonitorModule(ai, {});
        const warnings = await m.checkCorrectionStaleness([{ filePath: 'announcement-2026-10-09-1.md', content: 'Season 7 launches October 1' }]);
        assert.ok(warnings.some(w => w.correctionFile === 'core-facts.md'));
        const drafted = await m.draftCorrectionUpdates(warnings, [{ filePath: 'announcement-2026-10-09-1.md', content: 'x' }]);
        assert.strictEqual(drafted.find(d => d.correctionFile === 'core-facts.md').noChangeNeeded, true);
        assert.strictEqual(drafted.find(d => d.correctionFile === 'made-up.md').draftPath, null);
        assert.strictEqual(ai.calls.filter(c => c.model.includes('sonnet')).length, 1, 'no draft call for the invented name');
    } finally { box.cleanup(); }
});
